        /** @var null|Request $request */
        $request = $context['request'] ?? null;

        $page = $this->intValue($operation, 'page', 1);
        $limit = $this->intValue($operation, 'limit', 20);

        $ean = $this->stringValue($operation, 'ean');

        if ($ean !== null) {
